import {controller, target} from '@github/catalyst'
import {AT_COPILOT_VALUE} from '@github-ui/filter/providers'

const ANIMATION_DURATION = 200

type State = {visible: boolean; timer?: number}

@controller
export class CopilotMentionsHintElement extends HTMLElement {
  @target declare inputField: HTMLInputElement | HTMLTextAreaElement
  @target declare indicator: HTMLElement
  @target declare infoText: HTMLElement
  @target declare button: HTMLButtonElement

  #animState: State = {visible: false}

  connectedCallback() {
    // Guard: Make sure all required elements are present
    if (!this.inputField || !this.indicator || !this.infoText || !this.button) {
      return
    }

    // Initialize state based on current visibility
    // Consider it visible only if it's not sr-only (the hidden attribute is managed separately)
    const isVisible = !this.infoText.classList.contains('sr-only')
    this.#animState = {visible: isVisible}

    // Add event listeners to the input field
    this.inputField.addEventListener('input', this.#updateIndicator)
    this.inputField.addEventListener('change', this.#updateIndicator)
    this.inputField.addEventListener('click', this.#updateIndicator)
    this.inputField.addEventListener('keyup', this.#updateIndicator)
    this.inputField.addEventListener('select', this.#updateIndicator)

    // Add event listener to the toggle button
    this.button.addEventListener('click', this.#toggleInfoText)

    // Listen for form reset events
    const form = this.inputField.closest('form')
    if (form) {
      form.addEventListener('reset', this.#handleFormReset)
    }

    // Set initial state
    this.button.setAttribute('aria-expanded', 'false')

    // Trigger initial update
    this.#updateIndicator()
  }

  disconnectedCallback() {
    if (!this.inputField || !this.button) return

    // Clean up event listeners
    this.inputField.removeEventListener('input', this.#updateIndicator)
    this.inputField.removeEventListener('change', this.#updateIndicator)
    this.inputField.removeEventListener('click', this.#updateIndicator)
    this.inputField.removeEventListener('keyup', this.#updateIndicator)
    this.inputField.removeEventListener('select', this.#updateIndicator)
    this.button.removeEventListener('click', this.#toggleInfoText)

    // Remove form reset listener
    const form = this.inputField.closest('form')
    if (form) {
      form.removeEventListener('reset', this.#handleFormReset)
    }

    // Clear any pending timers
    if (this.#animState.timer) {
      clearTimeout(this.#animState.timer)
    }
  }

  #updateIndicator = () => {
    if (!this.inputField || !this.indicator || !this.infoText || !this.button) return

    const text = this.inputField.value
    const caret = this.inputField.selectionStart ?? 0

    // Escape special regex characters in AT_COPILOT_VALUE
    const escapedValue = AT_COPILOT_VALUE.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

    // Check for mention presence
    const hasCopilot = new RegExp(`(?:^|[^A-Za-z0-9])${escapedValue}(?:[^A-Za-z0-9]|$)`, 'i').test(text)

    // Check if caret is within any '@copilot ' (space included) — with +1 grace after match
    let inRange = false
    const re = new RegExp(`(?:^|[^a-zA-Z0-9])(${escapedValue}\\s?)`, 'gi')

    for (let m: RegExpExecArray | null; (m = re.exec(text)); ) {
      const mention = m[1]
      if (!mention) continue
      const start = m.index + (m[0].length - mention.length)
      const end = start + mention.length
      if (caret >= start && caret <= end) {
        inRange = true
        break
      }
    }

    if (!hasCopilot) {
      this.indicator.hidden = true
      this.inputField.classList.remove('pb-5')
      this.infoText.hidden = true
      this.infoText.classList.remove('sr-only') // reset
      this.#animState = {visible: false} // reset animation state
      this.button.classList.remove('is-expanded')
      this.button.style.backgroundColor = ''
      this.button.setAttribute('aria-expanded', 'false')
      return
    }

    // Mention exists so show row and reserve space
    this.indicator.hidden = false
    this.inputField.classList.add('pb-5')
    this.infoText.hidden = false

    // Caret-driven visibility
    const shouldShow = inRange

    // If we're transitioning from a state where there was no @copilot mention,
    // ensure sr-only is set correctly before animating
    if (!shouldShow && !this.#animState.visible) {
      this.infoText.classList.add('sr-only')
    }

    this.#animateInfoText(shouldShow)
    this.button.classList.toggle('is-expanded', shouldShow)
    this.button.style.backgroundColor = shouldShow ? 'var(--bgColor-muted)' : ''
    this.button.setAttribute('aria-expanded', shouldShow ? 'true' : 'false')
  }

  #toggleInfoText = (event: Event) => {
    if (!this.button) return

    event.preventDefault()
    event.stopPropagation()

    const nextVisible = !this.#animState.visible
    this.#animateInfoText(nextVisible)
    this.button.classList.toggle('is-expanded', nextVisible)
    this.button.style.backgroundColor = nextVisible ? 'var(--bgColor-muted)' : ''
    this.button.setAttribute('aria-expanded', nextVisible ? 'true' : 'false')
  }

  #handleFormReset = () => {
    // When the form is reset, the textarea value should be cleared.
    // Use setTimeout to defer the update to the next event loop tick,
    // making sure the form field values have been reset before we check them
    setTimeout(() => {
      this.#updateIndicator()
    }, 0)
  }

  #animateInfoText(makeVisible: boolean) {
    if (!this.infoText) return
    if (this.#animState.visible === makeVisible) return

    if (this.#animState.timer) {
      clearTimeout(this.#animState.timer)
      this.#animState.timer = undefined
    }

    // Keep in layout during animations
    this.infoText.hidden = false

    if (makeVisible) {
      this.infoText.classList.remove('sr-only')

      this.infoText.style.transition = 'none'
      this.infoText.style.transform = 'translateX(-5px)'
      void this.infoText.offsetWidth // force reflow

      this.infoText.style.transition = `transform ${ANIMATION_DURATION}ms ease-out`
      this.infoText.style.transform = 'translateX(0)'

      this.#animState.visible = true
    } else {
      this.infoText.style.transition = `transform ${ANIMATION_DURATION}ms ease-in`
      this.infoText.style.transform = 'translateX(-5px)'

      this.#animState.visible = false
      this.#animState.timer = window.setTimeout(() => {
        if (!this.infoText) return
        this.infoText.classList.add('sr-only')
        this.#animState.timer = undefined
      }, ANIMATION_DURATION)
    }
  }
}
